def print_board(board):
    """Print the Tic-Tac-Toe board."""
    for row in board:
        print(' | '.join(str(cell) for cell in row))
        print('-' * 9)

def is_winner(board, player):
    """Check if the given player has won the game."""
    # Check rows
    for row in board:
        if all(cell == player for cell in row):
            return True

    # Check columns
    for col in range(3):
        if all(board[row][col] == player for row in range(3)):
            return True

    # Check diagonals
    if board[0][0] == player and board[1][1] == player and board[2][2] == player:
        return True
    if board[0][2] == player and board[1][1] == player and board[2][0] == player:
        return True

    return False

def get_player_move(board, player):
    """Get the player's move."""
    while True:
        move = input(f"{player}'s turn. Enter the cell number: ")
        try:
            cell = int(move) - 1
            if 0 <= cell < 9 and board[cell // 3][cell % 3] == ' ':
                return cell
            else:
                print("That cell is already taken. Please try again.")
        except ValueError:
            print("Please enter a valid cell number (1-9).")

def play_tic_tac_toe():
    """Play a game of Tic-Tac-Toe."""
    board = [[' '] * 3 for _ in range(3)]
    player1, player2 = 'X', 'O'

    while True:
        print_board(board)

        if is_winner(board, player1):
            print(f"{player1} wins!")
            break
